package com.bank.compliance.service;

import com.bank.compliance.annotation.*;
import com.bank.compliance.dto.*;
import com.bank.compliance.model.ComplianceResult;
import jakarta.persistence.EntityManager;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.slf4j.MDC;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@RequiredArgsConstructor
@Slf4j
public class ComplianceCheckService {

    private final EntityManager entityManager;

    @LogExecutionTime("KYC Compliance Check")   // AOP: timing logged automatically
    @Auditable(action = "COMPLIANCE_CHECK")      // AOP: audit logged automatically
    @Transactional                                // AOP: transaction managed automatically
    public ComplianceResponse performCheck(ComplianceRequest request) {
        // PURE BUSINESS LOGIC — no timing code, no audit code, no TX code!
        log.info("Running {} check for {}", request.checkType(), request.accountId());

        long start = System.nanoTime();
        int riskScore = calculateRiskScore(request.accountId(), request.checkType());
        String result = riskScore >= 80 ? "HIGH_RISK" : riskScore >= 50 ? "MEDIUM" : "CLEAR";
        long elapsed = (System.nanoTime() - start) / 1_000_000;

        ComplianceResult entity = new ComplianceResult(
            request.accountId(), request.checkType(), result,
            riskScore, MDC.get("userId"), elapsed);
        entityManager.persist(entity);

        return new ComplianceResponse(
            request.accountId(), request.checkType(), result, riskScore, elapsed);
    }

    private int calculateRiskScore(String accountId, String checkType) {
        // Simulated ML scoring
        return (int) (Math.random() * 100);
    }
}
