// HandlerInterceptor: runs INSIDE Spring MVC (after DispatcherServlet matches handler)
package com.bank.compliance.interceptor;

import jakarta.servlet.http.*;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Component;
import org.springframework.web.servlet.HandlerInterceptor;

@Component
@Slf4j
public class RequestTimingInterceptor implements HandlerInterceptor {

    @Override
    public boolean preHandle(HttpServletRequest req, HttpServletResponse resp,
                              Object handler) {
        req.setAttribute("requestStartTime", System.nanoTime());
        return true;  // continue to controller
    }

    @Override
    public void afterCompletion(HttpServletRequest req, HttpServletResponse resp,
                                 Object handler, Exception ex) {
        long start = (long) req.getAttribute("requestStartTime");
        long elapsedMs = (System.nanoTime() - start) / 1_000_000;
        log.info("[INTERCEPTOR] {} {} → {} in {}ms",
            req.getMethod(), req.getRequestURI(), resp.getStatus(), elapsedMs);
    }
}
